    expect_vec3_near(world.editor.snap_grid, slayer3d_vec3_make(0.5f, 0.25f, 0.5f));
    EXPECT_FLOAT_EQ(world.editor.snap_rotation_degrees, 15.0f);
    EXPECT_TRUE(world.editor.snap_align_to_floor);
