    EXPECT_FLOAT_EQ(world.materials[0].albedo.z, 0.45f);
    EXPECT_FLOAT_EQ(world.materials[0].roughness, 0.8f);
    EXPECT_FLOAT_EQ(world.materials[0].tex_scale, 2.0f);
