    click_editor(scroll_up.x + scroll_up.w * 0.5f, scroll_up.y + scroll_up.h * 0.5f);
    click_editor(scroll_up.x + scroll_up.w * 0.5f, scroll_up.y + scroll_up.h * 0.5f);
    click_editor(scroll_up.x + scroll_up.w * 0.5f, scroll_up.y + scroll_up.h * 0.5f);
