TEST(GameDataRuntime, EditorShellDojoToolbarButtonsAreCompactCenteredAndLabeled)
{
    const std::filesystem::path dojo_path = editor_shell_dojo_data_path();
    ASSERT_TRUE(std::filesystem::exists(dojo_path)) << dojo_path;

    slayer3d_game_session *session = nullptr;
    ASSERT_TRUE(slayer3d_game_session_create(nullptr, &session));
    char error[512]{};
    slayer3d_game_data_runtime *runtime = nullptr;
    ASSERT_TRUE(slayer3d_game_data_load_file(dojo_path.string().c_str(), session, &runtime, error, sizeof(error)))
        << error;

    auto largest_ui_rect = [&](const char *name) {
        struct Capture
        {
            const char *name = nullptr;
            slayer3d_game_data_ui_rect rect{};
            float area = -1.0f;
            bool found = false;
        } capture{name, {}, -1.0f, false};
        auto collect = [](void *userdata, const slayer3d_game_data_ui_rect *rect) -> bool {
            auto *capture = static_cast<Capture *>(userdata);
            if (rect == nullptr || rect->name == nullptr || capture->name == nullptr ||
                SDL_strcmp(rect->name, capture->name) != 0)
            {
                return true;
            }
            const float area = rect->w * rect->h;
            if (area > capture->area)
            {
                capture->rect = *rect;
                capture->area = area;
                capture->found = true;
            }
            return true;
        };
        EXPECT_TRUE(slayer3d_game_data_for_each_ui_rect(runtime, collect, &capture));
        EXPECT_TRUE(capture.found) << name;
        return capture.rect;
    };
    auto visible_text = [&]() {
        struct Capture
        {
            std::vector<std::string> values;
        } capture;
        auto collect = [](void *userdata, const slayer3d_game_data_ui_text *text) -> bool {
            auto *capture = static_cast<Capture *>(userdata);
            if (text != nullptr && text->name != nullptr && text->text != nullptr &&
                std::string(text->name).rfind("ui.editor_shell.tool_toolbar.", 0) == 0)
            {
                capture->values.emplace_back(text->text);
            }
            return true;
        };
        slayer3d_game_data_ui_metrics metrics{};
        EXPECT_TRUE(slayer3d_game_data_for_each_ui_text_for_metrics(runtime, &metrics, collect, &capture));
        return capture.values;
    };
    auto contains_text = [](const std::vector<std::string> &values, const char *expected) {
        return std::find(values.begin(), values.end(), expected) != values.end();
    };

    const slayer3d_game_data_ui_rect menu_toolbar = largest_ui_rect("ui.editor_shell.toolbar");
    for (const char *name : {"ui.editor_shell.toolbar.file.button", "ui.editor_shell.toolbar.edit.button",
                             "ui.editor_shell.toolbar.selection.button", "ui.editor_shell.toolbar.groups.button",
                             "ui.editor_shell.toolbar.global.button", "ui.editor_shell.toolbar.actors.button",
                             "ui.editor_shell.toolbar.tools.button", "ui.editor_shell.toolbar.view.button",
                             "ui.editor_shell.toolbar.run.button", "ui.editor_shell.toolbar.debug.button",
                             "ui.editor_shell.toolbar.help.button"})
    {
        const slayer3d_game_data_ui_rect button = largest_ui_rect(name);
        EXPECT_NEAR(button.y + button.h * 0.5f, menu_toolbar.y + menu_toolbar.h * 0.5f, 0.001f) << name;
        EXPECT_GE(button.x, menu_toolbar.x) << name;
        EXPECT_LE(button.x + button.w, menu_toolbar.x + menu_toolbar.w) << name;
    }

    const slayer3d_game_data_ui_rect tool_toolbar = largest_ui_rect("ui.editor_shell.tool_toolbar");
    const char *tool_button_names[] = {"ui.editor_shell.tool_toolbar.select.button",
                                       "ui.editor_shell.tool_toolbar.brush.button",
                                       "ui.editor_shell.tool_toolbar.edge.button",
                                       "ui.editor_shell.tool_toolbar.clip.button",
                                       "ui.editor_shell.tool_toolbar.face.button",
                                       "ui.editor_shell.tool_toolbar.vertex.button",
                                       "ui.editor_shell.tool_toolbar.rotate.button",
                                       "ui.editor_shell.tool_toolbar.scale.button",
                                       "ui.editor_shell.tool_toolbar.shear.button",
                                       "ui.editor_shell.tool_toolbar.duplicate.button",
                                       "ui.editor_shell.tool_toolbar.flip_horizontal.button",
                                       "ui.editor_shell.tool_toolbar.flip_vertical.button",
                                       "ui.editor_shell.tool_toolbar.materials.button",
                                       "ui.editor_shell.tool_toolbar.grid.button"};
    float first_x = 0.0f;
    float last_right = 0.0f;
    for (size_t i = 0; i < SDL_arraysize(tool_button_names); ++i)
    {
        const slayer3d_game_data_ui_rect button = largest_ui_rect(tool_button_names[i]);
        if (i == 0)
            first_x = button.x;
        last_right = button.x + button.w;
        EXPECT_NEAR(button.y + button.h * 0.5f, tool_toolbar.y + tool_toolbar.h * 0.5f, 0.001f) << tool_button_names[i];
        EXPECT_GE(button.x, tool_toolbar.x) << tool_button_names[i];
        EXPECT_LE(button.x + button.w, tool_toolbar.x + tool_toolbar.w) << tool_button_names[i];
    }
    EXPECT_NEAR(first_x - tool_toolbar.x, tool_toolbar.x + tool_toolbar.w - last_right, 1.0f);

    const std::vector<std::string> labels = visible_text();
    EXPECT_TRUE(contains_text(labels, "Select (space)"));
    EXPECT_TRUE(contains_text(labels, "Brush Tool (b)"));
    EXPECT_TRUE(contains_text(labels, "Clip (c)"));
    EXPECT_TRUE(contains_text(labels, "Face (f)"));
    EXPECT_TRUE(contains_text(labels, "Vertex (v)"));
    EXPECT_TRUE(contains_text(labels, "Duplicate (d)"));
    EXPECT_TRUE(contains_text(labels, "Texture (m)"));

    slayer3d_game_data_destroy(runtime);
    slayer3d_game_session_destroy(session);
}

TEST(GameDataRuntime, EditorShellDojoGlobalLightingPanelConsumesInputAndShowsDefaults)
{
    const std::filesystem::path dojo_path = editor_shell_dojo_data_path();
    ASSERT_TRUE(std::filesystem::exists(dojo_path)) << dojo_path;

    slayer3d_game_session *session = nullptr;
    ASSERT_TRUE(slayer3d_game_session_create(nullptr, &session));
    char error[512]{};
    slayer3d_game_data_runtime *runtime = nullptr;
    ASSERT_TRUE(slayer3d_game_data_load_file(dojo_path.string().c_str(), session, &runtime, error, sizeof(error)))
        << error;

    slayer3d_signal_bus *bus = slayer3d_game_session_get_signal_bus(session);
    ASSERT_NE(bus, nullptr);
    const int global_signal = slayer3d_game_data_find_signal(runtime, "signal.editor.global.toggle");
    ASSERT_GE(global_signal, 0);
    slayer3d_signal_emit(bus, global_signal, nullptr);

    slayer3d_properties *scene_state = slayer3d_game_data_mutable_scene_state(runtime);
    ASSERT_NE(scene_state, nullptr);
    EXPECT_TRUE(slayer3d_properties_get_bool(scene_state, "editor.global.panel.open", false));

    struct TextCapture
    {
        slayer3d_game_data_runtime *runtime = nullptr;
        std::vector<std::string> values;
    } text_capture{runtime, {}};
    auto collect_text = [](void *userdata, const slayer3d_game_data_ui_text *text) -> bool {
        auto *capture = static_cast<TextCapture *>(userdata);
        if (text == nullptr || text->name == nullptr)
            return true;
        slayer3d_game_data_ui_text resolved{};
        bool visible = false;
        if (slayer3d_game_data_resolve_ui_text(capture->runtime, text, nullptr, &resolved, &visible) && visible &&
            resolved.text != nullptr && std::string(resolved.name).rfind("ui.editor_shell.global_panel.", 0) == 0)
        {
            capture->values.emplace_back(resolved.text);
        }
        return true;
    };
    ASSERT_TRUE(slayer3d_game_data_for_each_ui_text(runtime, collect_text, &text_capture));
    auto contains_text = [&](const char *expected) {
        return std::find(text_capture.values.begin(), text_capture.values.end(), expected) != text_capture.values.end();
    };
    EXPECT_TRUE(contains_text("Global Lighting"));
    EXPECT_TRUE(contains_text("54, 56, 64, 255"));
    EXPECT_TRUE(contains_text("12, 14, 18, 255"));
    EXPECT_TRUE(contains_text("balanced"));
    EXPECT_TRUE(contains_text("Plan Lighting"));
    EXPECT_TRUE(contains_text("not planned"));
    EXPECT_TRUE(contains_text("No lighting plan computed"));

    slayer3d_ui_layout_model *layout = nullptr;
    ASSERT_TRUE(slayer3d_ui_layout_create(&layout));
    ASSERT_TRUE(slayer3d_game_data_build_active_ui_widget_layout(runtime, 1280.0f, 720.0f, nullptr, layout));
    const slayer3d_ui_layout_hit_region *hit = slayer3d_ui_layout_hit_test(layout, 948.0f, 178.0f);
    ASSERT_NE(hit, nullptr);
    ASSERT_NE(hit->id, nullptr);
    EXPECT_NE(std::string(hit->id).find("ui.editor_shell.global_panel."), std::string::npos);
    slayer3d_ui_layout_destroy(layout);

    const int plan_signal = slayer3d_game_data_find_signal(runtime, "signal.editor.file.plan_lighting");
    ASSERT_GE(plan_signal, 0);
    slayer3d_signal_emit(bus, plan_signal, nullptr);
    EXPECT_TRUE(slayer3d_properties_get_bool(scene_state, "editor.lighting.plan.valid", false));
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.lighting.plan.total_count", -1), 0);
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.lighting.plan.runtime_count", -1), 0);
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.lighting.plan.bake_count", -1), 0);
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.lighting.plan.message", ""),
                 "lighting plan: 0 lights, 0 runtime, 0 bake");
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.lighting.plan.line3", ""),
                 "lighting plan runtime only");

    const int close_signal = slayer3d_game_data_find_signal(runtime, "signal.editor.global.close");
    ASSERT_GE(close_signal, 0);
    slayer3d_signal_emit(bus, close_signal, nullptr);
    EXPECT_FALSE(slayer3d_properties_get_bool(scene_state, "editor.global.panel.open", true));

    slayer3d_game_data_destroy(runtime);
    slayer3d_game_session_destroy(session);
}

TEST(GameDataRuntime, EditorShellDojoGlobalLightingControlsExportToMapJson)
{
    const std::filesystem::path dojo_path = editor_shell_dojo_data_path();
    ASSERT_TRUE(std::filesystem::exists(dojo_path)) << dojo_path;

    slayer3d_game_session *session = nullptr;
    ASSERT_TRUE(slayer3d_game_session_create(nullptr, &session));
    char error[512]{};
    slayer3d_game_data_runtime *runtime = nullptr;
    ASSERT_TRUE(slayer3d_game_data_load_file(dojo_path.string().c_str(), session, &runtime, error, sizeof(error)))
        << error;

    slayer3d_signal_bus *bus = slayer3d_game_session_get_signal_bus(session);
    ASSERT_NE(bus, nullptr);
    auto emit_signal = [&](const char *name) {
        const int signal = slayer3d_game_data_find_signal(runtime, name);
        ASSERT_GE(signal, 0) << name;
        slayer3d_signal_emit(bus, signal, nullptr);
    };

    emit_signal("signal.editor.global.toggle");
    emit_signal("signal.editor.global.preset.night");
    emit_signal("signal.editor.global.exposure.up");
    emit_signal("signal.editor.global.tonemap.next");
    emit_signal("signal.editor.global.quality.next");
    emit_signal("signal.editor.global.fog.next");

    slayer3d_properties *scene_state = slayer3d_game_data_mutable_scene_state(runtime);
    ASSERT_NE(scene_state, nullptr);
    const slayer3d_color ambient =
        slayer3d_properties_get_color(scene_state, "editor.global.ambient_light", slayer3d_color{0, 0, 0, 0});
    EXPECT_EQ(ambient.r, 20);
    EXPECT_EQ(ambient.g, 24);
    EXPECT_EQ(ambient.b, 42);
    EXPECT_FLOAT_EQ(slayer3d_properties_get_float(scene_state, "editor.global.exposure", 0.0f), 0.8f);
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.global.tonemap", ""), "reinhard");
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.global.lighting_preview_quality", ""),
                 "performance");
    EXPECT_EQ(slayer3d_game_data_world_light_upload_limit(runtime), 4);
    emit_signal("signal.editor.global.quality.next");
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.global.lighting_preview_quality", ""), "balanced");
    EXPECT_EQ(slayer3d_game_data_world_light_upload_limit(runtime), 8);
    emit_signal("signal.editor.global.quality.next");
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.global.lighting_preview_quality", ""), "quality");
    EXPECT_EQ(slayer3d_game_data_world_light_upload_limit(runtime), 16);
    slayer3d_properties_set_string(scene_state, "editor.global.lighting_preview_quality", "off");
    EXPECT_EQ(slayer3d_game_data_world_light_upload_limit(runtime), SLAYER3D_MAX_LIGHTS);
    slayer3d_properties_set_string(scene_state, "editor.global.lighting_preview_quality", "performance");
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.global.fog", ""), "exp");

    char *map_json = nullptr;
    size_t map_size = 0u;
    ASSERT_TRUE(slayer3d_game_data_export_editable_level_map_json(runtime, "brush.editor_shell.target", &map_json,
                                                                  &map_size, error, sizeof(error)))
        << error;
    slayer3d_map_document *document = nullptr;
    ASSERT_TRUE(slayer3d_map_load_json(map_json, map_size, nullptr, &document, error, sizeof(error))) << error;
    ASSERT_NE(document, nullptr);

    slayer3d_map_global_state global{};
    ASSERT_TRUE(slayer3d_map_get_global_state(document, &global));
    EXPECT_TRUE(global.has_ambient_light);
    EXPECT_EQ(global.ambient_light.r, 20);
    EXPECT_EQ(global.ambient_light.b, 42);
    EXPECT_TRUE(global.has_clear_color);
    EXPECT_EQ(global.clear_color.b, 12);
    EXPECT_TRUE(global.has_exposure);
    EXPECT_FLOAT_EQ(global.exposure, 0.8f);
    EXPECT_STREQ(global.tonemap, "reinhard");
    EXPECT_STREQ(global.lighting_preview_quality, "performance");
    EXPECT_TRUE(global.fog.enabled);
    EXPECT_STREQ(global.fog.mode, "exp");

    slayer3d_map_destroy(document);
    SDL_free(map_json);
    slayer3d_game_data_destroy(runtime);
    slayer3d_game_session_destroy(session);
}

TEST(GameDataRuntime, EditorShellDojoFaceDragUsesProjectedFaceNormalDirection)
{
    const std::filesystem::path dojo_path = editor_shell_dojo_data_path();
    ASSERT_TRUE(std::filesystem::exists(dojo_path)) << dojo_path;

    slayer3d_game_session *session = nullptr;
    ASSERT_TRUE(slayer3d_game_session_create(nullptr, &session));
    char error[512]{};
    slayer3d_game_data_runtime *runtime = nullptr;
    ASSERT_TRUE(slayer3d_game_data_load_file(dojo_path.string().c_str(), session, &runtime, error, sizeof(error)))
        << error;
    seed_editor_shell_test_cube(runtime);
    ASSERT_TRUE(slayer3d_game_data_update(runtime, 0.016f));

    slayer3d_signal_bus *bus = slayer3d_game_session_get_signal_bus(session);
    ASSERT_NE(bus, nullptr);
    const int mode_face_signal = slayer3d_game_data_find_signal(runtime, "signal.editor.mode.face");
    const int mode_select_signal = slayer3d_game_data_find_signal(runtime, "signal.editor.mode.select");
    ASSERT_GE(mode_face_signal, 0);
    ASSERT_GE(mode_select_signal, 0);
    slayer3d_signal_emit(bus, mode_face_signal, nullptr);

    const slayer3d_properties *scene_state = slayer3d_game_data_scene_state(runtime);
    ASSERT_NE(scene_state, nullptr);
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.mode", ""), "face");

    slayer3d_input_manager *input = slayer3d_game_session_get_input(session);
    ASSERT_NE(input, nullptr);
    SDL_Event motion{};
    motion.type = SDL_EVENT_MOUSE_MOTION;
    motion.motion.x = 640.0f;
    motion.motion.y = 340.0f;
    slayer3d_input_process_event(input, &motion);
    slayer3d_input_update(input, 1);
    ASSERT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));
    ASSERT_TRUE(slayer3d_properties_get_bool(scene_state, "editor.selection.hit", false));
    const slayer3d_value *selection_normal = slayer3d_properties_get_value(scene_state, "editor.selection.normal");
    ASSERT_NE(selection_normal, nullptr);
    ASSERT_EQ(selection_normal->type, SLAYER3D_VALUE_VEC3);
    slayer3d_camera3d camera{};
    ASSERT_TRUE(slayer3d_game_data_get_camera(runtime, slayer3d_game_data_active_camera(runtime), &camera));
    const slayer3d_vec3 forward = slayer3d_vec3_normalize(slayer3d_vec3_sub(camera.target, camera.position));
    const slayer3d_vec3 right = slayer3d_vec3_normalize(slayer3d_vec3_cross(forward, camera.up));
    const slayer3d_vec3 up_direction = slayer3d_vec3_normalize(slayer3d_vec3_cross(right, forward));
    const float projected_x = slayer3d_vec3_dot(selection_normal->as_vec3, right);
    const float projected_y = -slayer3d_vec3_dot(selection_normal->as_vec3, up_direction);
    const float projected_length = SDL_sqrtf(projected_x * projected_x + projected_y * projected_y);
    ASSERT_GT(projected_length, 0.000001f);
    ASSERT_GT(SDL_fabsf(projected_x), SDL_fabsf(projected_y)) << "fixture should exercise horizontal face swipes";
    const float drag_x = projected_x / projected_length * 48.0f;
    const float drag_y = projected_y / projected_length * 48.0f;

    SDL_Event down{};
    down.type = SDL_EVENT_MOUSE_BUTTON_DOWN;
    down.button.button = SDL_BUTTON_LEFT;
    down.button.x = motion.motion.x;
    down.button.y = motion.motion.y;
    slayer3d_input_process_event(input, &down);
    slayer3d_input_update(input, 2);
    ASSERT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));

    motion.motion.x = 640.0f + drag_x;
    motion.motion.y = 340.0f + drag_y;
    slayer3d_input_process_event(input, &motion);
    slayer3d_input_update(input, 3);
    ASSERT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));
    EXPECT_NEAR(slayer3d_properties_get_float(scene_state, "editor.brush.resize.distance", 0.0f), 1.0f, 0.001f);

    motion.motion.x = 640.0f - drag_x;
    motion.motion.y = 340.0f - drag_y;
    slayer3d_input_process_event(input, &motion);
    slayer3d_input_update(input, 4);
    ASSERT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));
    EXPECT_NEAR(slayer3d_properties_get_float(scene_state, "editor.brush.resize.distance", 0.0f), -1.0f, 0.001f);

    SDL_Event up{};
    up.type = SDL_EVENT_MOUSE_BUTTON_UP;
    up.button.button = SDL_BUTTON_LEFT;
    up.button.x = motion.motion.x;
    up.button.y = motion.motion.y;
    slayer3d_input_process_event(input, &up);
    slayer3d_input_update(input, 5);
    ASSERT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));

    slayer3d_game_data_brush_world brush_world{};
    ASSERT_TRUE(slayer3d_game_data_get_brush_world(runtime, "brush.editor_shell.target", &brush_world));
    ASSERT_EQ(brush_world.brush_count, 1);
    ASSERT_NE(brush_world.brushes[0].name, nullptr);
    const std::string brush_name = brush_world.brushes[0].name;
    const slayer3d_bounding_box before_select_drag = brush_world.brushes[0].bounds;
    slayer3d_signal_emit(bus, mode_select_signal, nullptr);
    ASSERT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.mode", ""), "select");

    motion.motion.x = 640.0f;
    motion.motion.y = 340.0f;
    slayer3d_input_process_event(input, &motion);
    slayer3d_input_update(input, 6);
    ASSERT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));
    down.button.x = motion.motion.x;
    down.button.y = motion.motion.y;
    slayer3d_input_process_event(input, &down);
    slayer3d_input_update(input, 7);
    ASSERT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));

    motion.motion.x = 760.0f;
    motion.motion.y = 430.0f;
    slayer3d_input_process_event(input, &motion);
    slayer3d_input_update(input, 8);
    ASSERT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));
    up.button.x = motion.motion.x;
    up.button.y = motion.motion.y;
    slayer3d_input_process_event(input, &up);
    slayer3d_input_update(input, 9);
    ASSERT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));
    ASSERT_TRUE(slayer3d_game_data_get_brush_world(runtime, "brush.editor_shell.target", &brush_world));
    const slayer3d_game_data_brush *after_drag_brush = nullptr;
    for (int i = 0; i < brush_world.brush_count; ++i)
    {
        if (brush_world.brushes[i].name != nullptr && brush_name == brush_world.brushes[i].name)
        {
            after_drag_brush = &brush_world.brushes[i];
            break;
        }
    }
    ASSERT_NE(after_drag_brush, nullptr);
    const float drag_dx = after_drag_brush->bounds.min.x - before_select_drag.min.x;
    const float drag_dz = after_drag_brush->bounds.min.z - before_select_drag.min.z;
    EXPECT_GT(SDL_fabsf(drag_dx) + SDL_fabsf(drag_dz), 0.001f);

    slayer3d_game_data_destroy(runtime);
    slayer3d_game_session_destroy(session);
}

TEST(GameDataRuntime, EditorShellDojoVertexModePublishesSourceVertexHandles)
{
    const std::filesystem::path dojo_path = editor_shell_dojo_data_path();
    ASSERT_TRUE(std::filesystem::exists(dojo_path)) << dojo_path;

    slayer3d_game_session *session = nullptr;
    ASSERT_TRUE(slayer3d_game_session_create(nullptr, &session));
    char error[512]{};
    slayer3d_game_data_runtime *runtime = nullptr;
    ASSERT_TRUE(slayer3d_game_data_load_file(dojo_path.string().c_str(), session, &runtime, error, sizeof(error)))
        << error;
    seed_editor_shell_test_cube(runtime);
    ASSERT_TRUE(slayer3d_game_data_update(runtime, 0.016f));
    select_editor_shell_test_cube(runtime);

    slayer3d_signal_bus *bus = slayer3d_game_session_get_signal_bus(session);
    ASSERT_NE(bus, nullptr);
    const int vertex_signal = slayer3d_game_data_find_signal(runtime, "signal.editor.mode.vertex");
    const int escape_signal = slayer3d_game_data_find_signal(runtime, "signal.editor.escape");
    ASSERT_GE(vertex_signal, 0);
    ASSERT_GE(escape_signal, 0);
    slayer3d_signal_emit(bus, vertex_signal, nullptr);

    const slayer3d_properties *scene_state = slayer3d_game_data_scene_state(runtime);
    ASSERT_NE(scene_state, nullptr);
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.mode", ""), "vertex");
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.tool.mode", ""), "vertex");
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.tool.last_action", ""), "vertex tool");

    auto visible_ui_rect = [&](const char *name) {
        struct RectNameCapture
        {
            const slayer3d_game_data_runtime *runtime = nullptr;
            const char *name = nullptr;
            bool found = false;
        } capture{runtime, name, false};
        auto capture_rect = [](void *userdata, const slayer3d_game_data_ui_rect *rect) -> bool {
            auto *capture = static_cast<RectNameCapture *>(userdata);
            if (rect == nullptr || rect->name == nullptr || capture->name == nullptr ||
                SDL_strcmp(rect->name, capture->name) != 0)
            {
                return true;
            }
            if (slayer3d_game_data_ui_rect_is_visible(capture->runtime, rect, nullptr))
            {
                capture->found = true;
                return false;
            }
            return true;
        };
        EXPECT_TRUE(slayer3d_game_data_for_each_ui_rect(runtime, capture_rect, &capture));
        return capture.found;
    };
    EXPECT_TRUE(visible_ui_rect("ui.editor_shell.tool_toolbar.vertex.selected"));

    struct VertexDebugCapture
    {
        int handles = 0;
        bool saw_vertex_id = false;
    } vertex_debug;
    auto capture_vertex_handles = [](void *userdata,
                                     const slayer3d_game_data_editor_debug_primitive *primitive) -> bool {
        auto *capture = static_cast<VertexDebugCapture *>(userdata);
        if (primitive != nullptr && primitive->type == SLAYER3D_GAME_DATA_EDITOR_DEBUG_VERTEX_HANDLE)
        {
            capture->handles++;
            if (primitive->element_name != nullptr &&
                std::string(primitive->element_name).find("brush.target.cube.vertex.") == 0)
            {
                capture->saw_vertex_id = true;
            }
        }
        return true;
    };
    ASSERT_TRUE(
        slayer3d_game_data_for_each_active_editor_debug_primitive(runtime, capture_vertex_handles, &vertex_debug));
    EXPECT_GE(vertex_debug.handles, 8);
    EXPECT_TRUE(vertex_debug.saw_vertex_id);

    SDL_Event motion{};
    motion.type = SDL_EVENT_MOUSE_MOTION;
    motion.motion.x = 640.0f;
    motion.motion.y = 340.0f;
    slayer3d_input_manager *input = slayer3d_game_session_get_input(session);
    ASSERT_NE(input, nullptr);
    slayer3d_input_process_event(input, &motion);
    slayer3d_input_update(input, 1);
    ASSERT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));
    EXPECT_TRUE(slayer3d_properties_get_bool(scene_state, "editor.vertex.hover.hit", false));
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.vertex.hover.brush", ""), "brush.target.cube");
    EXPECT_NE(std::string(slayer3d_properties_get_string(scene_state, "editor.vertex.hover.vertex", ""))
                  .find("brush.target.cube.vertex."),
              std::string::npos);
    EXPECT_GE(slayer3d_properties_get_int(scene_state, "editor.vertex.hover.index", -1), 0);
    EXPECT_GE(slayer3d_properties_get_int(scene_state, "editor.vertex.hover.shared_count", 0), 1);

    SDL_Event click{};
    click.type = SDL_EVENT_MOUSE_BUTTON_DOWN;
    click.button.button = SDL_BUTTON_LEFT;
    click.button.x = motion.motion.x;
    click.button.y = motion.motion.y;
    slayer3d_input_process_event(input, &click);
    slayer3d_input_update(input, 2);
    ASSERT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.vertex.selection.count", 0),
              slayer3d_properties_get_int(scene_state, "editor.vertex.hover.shared_count", 0));
    EXPECT_TRUE(slayer3d_properties_get_bool(scene_state, "editor.vertex.hover.selected", false));
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.tool.last_action", ""), "vertex selected");
    EXPECT_NE(std::string(slayer3d_properties_get_string(scene_state, "editor.vertex.selection.vertex", ""))
                  .find("brush.target.cube.vertex."),
              std::string::npos);

    struct SelectedVertexHandleCapture
    {
        int selected_handles = 0;
        int hovered_handles = 0;
        int hover_labels = 0;
        int base_handles = 0;
        bool selected_handle_is_red = false;
        bool hover_label_has_coordinates = false;
    } selected_vertex_debug;
    auto capture_selected_vertex_handles = [](void *userdata,
                                              const slayer3d_game_data_editor_debug_primitive *primitive) -> bool {
        auto *capture = static_cast<SelectedVertexHandleCapture *>(userdata);
        if (primitive == nullptr)
            return true;
        if (primitive->type == SLAYER3D_GAME_DATA_EDITOR_DEBUG_VERTEX_HANDLE)
            capture->base_handles++;
        if (primitive->type == SLAYER3D_GAME_DATA_EDITOR_DEBUG_VERTEX_SELECTED_HANDLE)
        {
            capture->selected_handles++;
            if (primitive->color.r >= 240 && primitive->color.g <= 64 && primitive->color.b <= 64)
                capture->selected_handle_is_red = true;
        }
        if (primitive->type == SLAYER3D_GAME_DATA_EDITOR_DEBUG_VERTEX_HOVER_HANDLE)
            capture->hovered_handles++;
        if (primitive->type == SLAYER3D_GAME_DATA_EDITOR_DEBUG_VERTEX_HOVER_LABEL)
        {
            capture->hover_labels++;
            const std::string label = primitive->text;
            if (label.find("X ") != std::string::npos && label.find("Y ") != std::string::npos &&
                label.find("Z ") != std::string::npos)
            {
                capture->hover_label_has_coordinates = true;
            }
        }
        return true;
    };
    ASSERT_TRUE(slayer3d_game_data_for_each_active_editor_debug_primitive(runtime, capture_selected_vertex_handles,
                                                                          &selected_vertex_debug));
    EXPECT_GE(selected_vertex_debug.selected_handles, 1);
    EXPECT_GE(selected_vertex_debug.hovered_handles, 1);
    EXPECT_GE(selected_vertex_debug.hover_labels, 1);
    EXPECT_LT(selected_vertex_debug.base_handles, vertex_debug.handles);
    EXPECT_TRUE(selected_vertex_debug.selected_handle_is_red);
    EXPECT_TRUE(selected_vertex_debug.hover_label_has_coordinates);

    click.type = SDL_EVENT_MOUSE_BUTTON_UP;
    slayer3d_input_process_event(input, &click);
    slayer3d_input_update(input, 3);
    ASSERT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));

    SDL_SetModState(SDL_KMOD_SHIFT);
    click.type = SDL_EVENT_MOUSE_BUTTON_DOWN;
    slayer3d_input_process_event(input, &click);
    slayer3d_input_update(input, 4);
    ASSERT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));
    SDL_SetModState(SDL_KMOD_NONE);
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.vertex.selection.count", -1), 0);
    EXPECT_FALSE(slayer3d_properties_get_bool(scene_state, "editor.vertex.hover.selected", true));
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.tool.last_action", ""), "vertex deselected");

    click.type = SDL_EVENT_MOUSE_BUTTON_UP;
    slayer3d_input_process_event(input, &click);
    slayer3d_input_update(input, 5);
    ASSERT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));

    click.type = SDL_EVENT_MOUSE_BUTTON_DOWN;
    slayer3d_input_process_event(input, &click);
    slayer3d_input_update(input, 6);
    ASSERT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));
    EXPECT_GT(slayer3d_properties_get_int(scene_state, "editor.vertex.selection.count", 0), 0);

    slayer3d_signal_emit(bus, escape_signal, nullptr);
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.vertex.selection.count", -1), 0);
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.mode", ""), "vertex");
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.tool.last_action", ""),
                 "vertex selection cleared");
    SelectedVertexHandleCapture deselected_vertex_debug{};
    ASSERT_TRUE(slayer3d_game_data_for_each_active_editor_debug_primitive(runtime, capture_selected_vertex_handles,
                                                                          &deselected_vertex_debug));
    EXPECT_EQ(deselected_vertex_debug.selected_handles, 0);
    slayer3d_signal_emit(bus, escape_signal, nullptr);
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.mode", ""), "select");
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.tool.mode", ""), "select");
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.selection.count", -1), 1);

    slayer3d_game_data_destroy(runtime);
    slayer3d_game_session_destroy(session);
}

