    auto press_save_chord = [&](SDL_Keymod modifiers, Uint64 frame) {
        SDL_SetModState(modifiers);
        SDL_Event key{};
        key.type = SDL_EVENT_KEY_DOWN;
        key.key.scancode = SDL_SCANCODE_S;
        key.key.mod = modifiers;
        slayer3d_input_process_event(input, &key);
        slayer3d_input_update(input, frame);
        const bool pressed = slayer3d_input_is_pressed(input, export_action_id);
        key.type = SDL_EVENT_KEY_UP;
        slayer3d_input_process_event(input, &key);
        slayer3d_input_update(input, frame + 1U);
        SDL_SetModState(SDL_KMOD_NONE);
        return pressed;
    };
    auto press_key = [&](SDL_Scancode scancode, Uint64 frame) {
        SDL_Event key{};
        key.type = SDL_EVENT_KEY_DOWN;
        key.key.scancode = scancode;
        slayer3d_input_process_event(input, &key);
        slayer3d_input_update(input, frame);
        const bool pressed = slayer3d_input_is_pressed(input, select_mode_action_id);
        EXPECT_TRUE(slayer3d_game_data_update(runtime, 0.016f));
        key.type = SDL_EVENT_KEY_UP;
        slayer3d_input_process_event(input, &key);
        slayer3d_input_update(input, frame + 1U);
        return pressed;
    };
    auto press_key_for_action = [&](SDL_Scancode scancode, int action_id, Uint64 frame) {
        SDL_Event key{};
        key.type = SDL_EVENT_KEY_DOWN;
        key.key.scancode = scancode;
        slayer3d_input_process_event(input, &key);
        slayer3d_input_update(input, frame);
        const bool pressed = slayer3d_input_is_pressed(input, action_id);
        EXPECT_TRUE(slayer3d_game_data_update(runtime, 0.016f));
        key.type = SDL_EVENT_KEY_UP;
        slayer3d_input_process_event(input, &key);
        slayer3d_input_update(input, frame + 1U);
        return pressed;
    };
    auto press_key_with_modifiers_for_action = [&](SDL_Scancode scancode, SDL_Keymod modifiers, int action_id,
                                                   Uint64 frame) {
        SDL_SetModState(modifiers);
        SDL_Event key{};
        key.type = SDL_EVENT_KEY_DOWN;
        key.key.scancode = scancode;
        key.key.mod = modifiers;
        slayer3d_input_process_event(input, &key);
        slayer3d_input_update(input, frame);
        const bool pressed = slayer3d_input_is_pressed(input, action_id);
        EXPECT_TRUE(slayer3d_game_data_update(runtime, 0.016f));
        key.type = SDL_EVENT_KEY_UP;
        slayer3d_input_process_event(input, &key);
        slayer3d_input_update(input, frame + 1U);
        SDL_SetModState(SDL_KMOD_NONE);
        return pressed;
    };
