    auto brush_bounds = [&](const std::string &name) {
        const slayer3d_game_data_brush_world brush_world = world();
        for (int i = 0; i < brush_world.brush_count; ++i)
        {
            const slayer3d_game_data_brush &candidate = brush_world.brushes[i];
            if (candidate.name != nullptr && name == candidate.name)
                return candidate.bounds;
        }
        ADD_FAILURE() << "brush not found: " << name;
        return slayer3d_bounding_box{slayer3d_vec3_make(0.0f, 0.0f, 0.0f), slayer3d_vec3_make(0.0f, 0.0f, 0.0f)};
    };
    auto visible_ui_text = [&](const char *prefix) {
        std::vector<std::string> values;
        slayer3d_game_data_ui_metrics metrics{};
        struct PrefixCapture
        {
            const slayer3d_game_data_runtime *runtime = nullptr;
            const slayer3d_game_data_ui_metrics *metrics = nullptr;
            std::vector<std::string> *values = nullptr;
            const char *prefix = nullptr;
        };
        auto capture_with_prefix = [](void *userdata, const slayer3d_game_data_ui_text *text) -> bool {
            auto *capture = static_cast<PrefixCapture *>(userdata);
            if (text == nullptr || text->name == nullptr || capture->values == nullptr || capture->prefix == nullptr ||
                std::string(text->name).rfind(capture->prefix, 0) != 0 ||
                !slayer3d_game_data_ui_text_is_visible(capture->runtime, text, capture->metrics))
            {
                return true;
            }
            char formatted[768]{};
            if (slayer3d_game_data_format_ui_text(capture->runtime, text, capture->metrics, formatted,
                                                  sizeof(formatted)))
                capture->values->emplace_back(formatted);
            else
                capture->values->emplace_back(text->text != nullptr ? text->text : "");
            return true;
        };
        PrefixCapture capture_state{runtime, &metrics, &values, prefix};
        EXPECT_TRUE(
            slayer3d_game_data_for_each_ui_text_for_metrics(runtime, &metrics, capture_with_prefix, &capture_state));
        return values;
    };
    auto contains_ui_text = [](const std::vector<std::string> &values, const char *expected) {
        for (const std::string &value : values)
        {
            if (value == expected)
                return true;
        }
        return false;
    };
    auto visible_ui_rect = [&](const char *name) {
        struct RectNameCapture
        {
            const slayer3d_game_data_runtime *runtime = nullptr;
            const char *name = nullptr;
            bool found = false;
        } capture{runtime, name, false};
        auto capture_rect = [](void *userdata, const slayer3d_game_data_ui_rect *rect) -> bool {
            auto *capture = static_cast<RectNameCapture *>(userdata);
            if (rect == nullptr || rect->name == nullptr || capture->name == nullptr ||
                SDL_strcmp(rect->name, capture->name) != 0)
            {
                return true;
            }
            if (slayer3d_game_data_ui_rect_is_visible(capture->runtime, rect, nullptr))
            {
                capture->found = true;
                return false;
            }
            return true;
        };
        EXPECT_TRUE(slayer3d_game_data_for_each_ui_rect(runtime, capture_rect, &capture));
        return capture.found;
    };
    auto ui_rect = [&](const char *name) {
        struct RectCapture
        {
            const slayer3d_game_data_runtime *runtime = nullptr;
            const char *name = nullptr;
            slayer3d_game_data_ui_rect rect{};
            bool found = false;
        } capture{runtime, name, {}, false};
        auto capture_rect = [](void *userdata, const slayer3d_game_data_ui_rect *rect) -> bool {
            auto *capture = static_cast<RectCapture *>(userdata);
            if (rect == nullptr || rect->name == nullptr || capture->name == nullptr ||
                SDL_strcmp(rect->name, capture->name) != 0)
            {
                return true;
            }
            if (slayer3d_game_data_ui_rect_is_visible(capture->runtime, rect, nullptr))
            {
                capture->rect = *rect;
                capture->found = true;
                return false;
            }
            return true;
        };
        EXPECT_TRUE(slayer3d_game_data_for_each_ui_rect(runtime, capture_rect, &capture));
        if (!capture.found)
            ADD_FAILURE() << "visible rect not found: " << (name != nullptr ? name : "<null>");
        return capture.rect;
    };
    auto visible_ui_rect_color = [&](const char *name, slayer3d_color *out_color) {
        struct RectColorCapture
        {
            const slayer3d_game_data_runtime *runtime = nullptr;
            const char *name = nullptr;
            slayer3d_color *out_color = nullptr;
            bool found = false;
        } capture{runtime, name, out_color, false};
        auto capture_rect = [](void *userdata, const slayer3d_game_data_ui_rect *rect) -> bool {
            auto *capture = static_cast<RectColorCapture *>(userdata);
            if (rect == nullptr || rect->name == nullptr || capture->name == nullptr ||
                SDL_strcmp(rect->name, capture->name) != 0)
            {
                return true;
            }
            if (slayer3d_game_data_ui_rect_is_visible(capture->runtime, rect, nullptr))
            {
                if (capture->out_color != nullptr)
                    *capture->out_color = rect->color;
                capture->found = true;
                return false;
            }
            return true;
        };
        EXPECT_TRUE(slayer3d_game_data_for_each_ui_rect(runtime, capture_rect, &capture));
        return capture.found;
    };
