TEST(GameDataRuntime, EditorShellDojoBrushSelectionSupportsAdditiveModifiers)
{
    const std::filesystem::path dojo_path = editor_shell_dojo_data_path();
    ASSERT_TRUE(std::filesystem::exists(dojo_path)) << dojo_path;

    slayer3d_game_session *session = nullptr;
    ASSERT_TRUE(slayer3d_game_session_create(nullptr, &session));
    char error[512]{};
    slayer3d_game_data_runtime *runtime = nullptr;
    ASSERT_TRUE(slayer3d_game_data_load_file(dojo_path.string().c_str(), session, &runtime, error, sizeof(error)))
        << error;

    const slayer3d_properties *scene_state = slayer3d_game_data_scene_state(runtime);
    ASSERT_NE(scene_state, nullptr);
    slayer3d_signal_bus *bus = slayer3d_game_session_get_signal_bus(session);
    ASSERT_NE(bus, nullptr);
    auto emit_signal = [&](const char *name) {
        const int signal = slayer3d_game_data_find_signal(runtime, name);
        EXPECT_GE(signal, 0) << name;
        if (signal >= 0)
            slayer3d_signal_emit(bus, signal, nullptr);
    };

    editor_brush_source_prefab_result first_result{};
    const int first_min[3] = {0, 0, 0};
    const int first_max[3] = {1000, 1000, 1000};
    ASSERT_TRUE(slayer3d_game_data_create_editor_source_box_brush(
        runtime, "brush.editor_shell.target", "mat.editor.floor", SLAYER3D_GAME_DATA_BRUSH_CONTENT_SOLID, first_min,
        first_max, &first_result));
    ASSERT_TRUE(first_result.valid);
    ASSERT_STRNE(first_result.brush_name, "");

    editor_brush_source_prefab_result second_result{};
    const int second_min[3] = {2000, 0, 0};
    const int second_max[3] = {3000, 1000, 1000};
    ASSERT_TRUE(slayer3d_game_data_create_editor_source_box_brush(
        runtime, "brush.editor_shell.target", "mat.editor.wall", SLAYER3D_GAME_DATA_BRUSH_CONTENT_SOLID, second_min,
        second_max, &second_result));
    ASSERT_TRUE(second_result.valid);
    ASSERT_STRNE(second_result.brush_name, "");

    auto brush_index = [&](const char *brush_name) {
        slayer3d_game_data_brush_world brush_world{};
        EXPECT_TRUE(slayer3d_game_data_get_brush_world(runtime, "brush.editor_shell.target", &brush_world));
        for (int i = 0; i < brush_world.brush_count; ++i)
        {
            const slayer3d_game_data_brush &brush = brush_world.brushes[i];
            if (brush.name != nullptr && SDL_strcmp(brush.name, brush_name) == 0)
                return i;
        }
        ADD_FAILURE() << "brush not found: " << (brush_name != nullptr ? brush_name : "<null>");
        return -1;
    };

    slayer3d_game_data_editor_selection first_selection{};
    slayer3d_game_data_editor_selection second_selection{};
    ASSERT_TRUE(editor_selection_from_brush_index(runtime, "brush.editor_shell.target",
                                                  brush_index(first_result.brush_name), -1, &first_selection));
    ASSERT_TRUE(editor_selection_from_brush_index(runtime, "brush.editor_shell.target",
                                                  brush_index(second_result.brush_name), -1, &second_selection));

    SDL_SetModState(SDL_KMOD_NONE);
    ASSERT_TRUE(editor_select_mode_primary_click(runtime, &first_selection));
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.selection.count", 0), 1);
    EXPECT_FALSE(slayer3d_properties_get_bool(scene_state, "editor.selection.multiple", true));
    slayer3d_game_data_editor_selection active_selection{};
    ASSERT_TRUE(slayer3d_game_data_get_active_editor_selection(runtime, &active_selection));
    EXPECT_STREQ(active_selection.element_name, first_result.brush_name);
    ASSERT_NE(active_selection.element_editor, nullptr);
    EXPECT_STREQ(active_selection.element_editor->stable_id, first_result.brush_name);
    EXPECT_NEAR(active_selection.bounds.max.x - active_selection.bounds.min.x, 1.0f, 0.001f);
    EXPECT_NEAR(active_selection.bounds.max.y - active_selection.bounds.min.y, 1.0f, 0.001f);
    EXPECT_NEAR(active_selection.bounds.max.z - active_selection.bounds.min.z, 1.0f, 0.001f);
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.inspector.selection.kind", ""), "Brush");
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.inspector.selection.title", ""),
                 first_result.brush_name);
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.inspector.selection.count", ""), "1 selected");
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.inspector.selection.size", ""),
                 "1.000, 1.000, 1.000");
    EXPECT_TRUE(slayer3d_properties_get_bool(scene_state, "editor.inspector.brush.editable", false));
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.inspector.selection.color", ""), "default");
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.inspector.brush.color.r", 0), 180);
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.inspector.brush.color.g", 0), 184);
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.inspector.brush.color.b", 0), 192);
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.inspector.brush.color.a", 0), 255);

    emit_signal("signal.editor.inspector.brush.color.r.up");
    emit_signal("signal.editor.inspector.brush.color.g.down");
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.inspector.brush.color.r", 0), 196);
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.inspector.brush.color.g", 0), 168);
    emit_signal("signal.editor.inspector.brush.color.apply");
    slayer3d_game_data_brush_world colored_world{};
    ASSERT_TRUE(slayer3d_game_data_get_brush_world(runtime, "brush.editor_shell.target", &colored_world));
    const int colored_first_index = brush_index(first_result.brush_name);
    ASSERT_GE(colored_first_index, 0);
    ASSERT_LT(colored_first_index, colored_world.brush_count);
    for (int i = 0; i < colored_world.brushes[colored_first_index].face_count; ++i)
    {
        const slayer3d_game_data_brush_face &face = colored_world.brushes[colored_first_index].faces[i];
        EXPECT_TRUE(face.has_color);
        EXPECT_EQ(face.color.r, 196);
        EXPECT_EQ(face.color.g, 168);
        EXPECT_EQ(face.color.b, 192);
        EXPECT_EQ(face.color.a, 255);
    }
    ASSERT_TRUE(editor_selection_from_brush_index(runtime, "brush.editor_shell.target",
                                                  brush_index(first_result.brush_name), -1, &first_selection));
    ASSERT_TRUE(editor_selection_from_brush_index(runtime, "brush.editor_shell.target",
                                                  brush_index(second_result.brush_name), -1, &second_selection));

    SDL_SetModState(SDL_KMOD_CTRL);
    ASSERT_TRUE(editor_select_mode_primary_click(runtime, &second_selection));
    SDL_SetModState(SDL_KMOD_NONE);
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.selection.count", 0), 2);
    EXPECT_TRUE(slayer3d_properties_get_bool(scene_state, "editor.selection.multiple", false));
    ASSERT_TRUE(slayer3d_game_data_get_active_editor_selection(runtime, &active_selection));
    EXPECT_STREQ(active_selection.element_name, second_result.brush_name);
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.inspector.selection.kind", ""), "Brushes");
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.inspector.selection.title", ""), "2 Brushes");
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.inspector.selection.count", ""), "2 selected");
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.inspector.selection.position", ""),
                 "1.500, 0.500, 0.500");
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.inspector.selection.size", ""),
                 "3.000, 1.000, 1.000");

    SDL_SetModState(SDL_KMOD_GUI);
    ASSERT_TRUE(editor_select_mode_primary_click(runtime, &first_selection));
    SDL_SetModState(SDL_KMOD_NONE);
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.selection.count", 0), 1);
    EXPECT_FALSE(slayer3d_properties_get_bool(scene_state, "editor.selection.multiple", true));
    ASSERT_TRUE(slayer3d_game_data_get_active_editor_selection(runtime, &active_selection));
    EXPECT_STREQ(active_selection.element_name, second_result.brush_name);

    SDL_SetModState(SDL_KMOD_SHIFT);
    ASSERT_TRUE(editor_select_mode_primary_click(runtime, &first_selection));
    SDL_SetModState(SDL_KMOD_NONE);
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.selection.count", 0), 2);
    ASSERT_TRUE(slayer3d_game_data_get_active_editor_selection(runtime, &active_selection));
    EXPECT_STREQ(active_selection.element_name, first_result.brush_name);

    slayer3d_game_data_editor_selection empty_selection{};
    SDL_SetModState(SDL_KMOD_CTRL);
    ASSERT_TRUE(editor_select_mode_primary_click(runtime, &empty_selection));
    SDL_SetModState(SDL_KMOD_NONE);
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.selection.count", 0), 2);
    ASSERT_TRUE(slayer3d_game_data_get_active_editor_selection(runtime, &active_selection));
    EXPECT_STREQ(active_selection.element_name, first_result.brush_name);

    ASSERT_TRUE(editor_select_mode_primary_click(runtime, &empty_selection));
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.selection.count", -1), 0);
    EXPECT_FALSE(slayer3d_game_data_get_active_editor_selection(runtime, &active_selection));
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.inspector.selection.kind", ""), "none");
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.inspector.selection.title", ""), "No selection");
    EXPECT_FALSE(slayer3d_properties_get_bool(scene_state, "editor.inspector.brush.editable", true));

    SDL_SetModState(SDL_KMOD_NONE);
    slayer3d_game_data_destroy(runtime);
    slayer3d_game_session_destroy(session);
}

TEST(GameDataRuntime, EditorShellDojoBrushKeyboardNudgeUsesCameraRelativeDirection)
{
    const std::filesystem::path dojo_path = editor_shell_dojo_data_path();
    ASSERT_TRUE(std::filesystem::exists(dojo_path)) << dojo_path;

    slayer3d_game_session *session = nullptr;
    ASSERT_TRUE(slayer3d_game_session_create(nullptr, &session));
    char error[512]{};
    slayer3d_game_data_runtime *runtime = nullptr;
    ASSERT_TRUE(slayer3d_game_data_load_file(dojo_path.string().c_str(), session, &runtime, error, sizeof(error)))
        << error;
    seed_editor_shell_test_cube(runtime);
    ASSERT_TRUE(slayer3d_game_data_update(runtime, 0.016f));
    select_editor_shell_test_cube(runtime);

    slayer3d_properties *scene_state = slayer3d_game_data_mutable_scene_state(runtime);
    ASSERT_NE(scene_state, nullptr);
    slayer3d_properties_set_float(scene_state, "editor.grid.size", 1.0f);

    auto brush_bounds = [&]() {
        slayer3d_game_data_brush_world world{};
        EXPECT_TRUE(slayer3d_game_data_get_brush_world(runtime, "brush.editor_shell.target", &world));
        for (int i = 0; i < world.brush_count; ++i)
        {
            const slayer3d_game_data_brush &brush = world.brushes[i];
            if (brush.name != nullptr && SDL_strcmp(brush.name, "brush.target.cube") == 0)
                return brush.bounds;
        }
        ADD_FAILURE() << "brush.target.cube not found";
        return slayer3d_bounding_box{};
    };

    slayer3d_input_manager *input = slayer3d_game_session_get_input(session);
    ASSERT_NE(input, nullptr);
    int frame = 0;
    auto press_key = [&](SDL_Scancode scancode) {
        SDL_Event key{};
        key.type = SDL_EVENT_KEY_DOWN;
        key.key.scancode = scancode;
        slayer3d_input_process_event(input, &key);
        slayer3d_input_update(input, ++frame);
        ASSERT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));
        key.type = SDL_EVENT_KEY_UP;
        slayer3d_input_process_event(input, &key);
        slayer3d_input_update(input, ++frame);
        ASSERT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));
    };

    slayer3d_camera3d default_camera{};
    ASSERT_TRUE(slayer3d_game_data_get_camera(runtime, "camera.editor_shell.viewport", &default_camera));
    const slayer3d_vec3 default_forward =
        slayer3d_vec3_normalize(slayer3d_vec3_sub(default_camera.target, default_camera.position));
    ASSERT_GT(default_forward.x, 0.0f);
    ASSERT_GT(SDL_fabsf(default_forward.x), SDL_fabsf(default_forward.z));

    const slayer3d_bounding_box before = brush_bounds();
    press_key(SDL_SCANCODE_UP);
    const slayer3d_bounding_box after_default_up = brush_bounds();
    EXPECT_NEAR(after_default_up.min.x, before.min.x + 1.0f, 0.001f);
    EXPECT_NEAR(after_default_up.max.x, before.max.x + 1.0f, 0.001f);
    EXPECT_NEAR(after_default_up.min.z, before.min.z, 0.001f);
    EXPECT_NEAR(after_default_up.max.z, before.max.z, 0.001f);

    slayer3d_registered_actor *editor_camera = slayer3d_game_data_find_actor(runtime, "entity.editor_shell.camera");
    ASSERT_NE(editor_camera, nullptr);
    const float yaw = slayer3d_properties_get_float(editor_camera->props, "yaw", 0.0f);
    slayer3d_properties_set_float(editor_camera->props, "yaw", yaw + 3.14159265f);

    slayer3d_camera3d reversed_camera{};
    ASSERT_TRUE(slayer3d_game_data_get_camera(runtime, "camera.editor_shell.viewport", &reversed_camera));
    const slayer3d_vec3 reversed_forward =
        slayer3d_vec3_normalize(slayer3d_vec3_sub(reversed_camera.target, reversed_camera.position));
    ASSERT_LT(reversed_forward.x, 0.0f);
    ASSERT_GT(SDL_fabsf(reversed_forward.x), SDL_fabsf(reversed_forward.z));

    press_key(SDL_SCANCODE_UP);
    const slayer3d_bounding_box after_reversed_up = brush_bounds();
    EXPECT_NEAR(after_reversed_up.min.x, before.min.x, 0.001f);
    EXPECT_NEAR(after_reversed_up.max.x, before.max.x, 0.001f);
    EXPECT_NEAR(after_reversed_up.min.z, before.min.z, 0.001f);
    EXPECT_NEAR(after_reversed_up.max.z, before.max.z, 0.001f);
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.tool.last_action", ""), "moved 1 selected brush");

    slayer3d_game_data_destroy(runtime);
    slayer3d_game_session_destroy(session);
}

TEST(GameDataRuntime, EditorShellDojoHorizontalFlipToolbarMirrorsMultiSelection)
{
    const std::filesystem::path dojo_path = editor_shell_dojo_data_path();
    ASSERT_TRUE(std::filesystem::exists(dojo_path)) << dojo_path;

    slayer3d_game_session *session = nullptr;
    ASSERT_TRUE(slayer3d_game_session_create(nullptr, &session));
    char error[512]{};
    slayer3d_game_data_runtime *runtime = nullptr;
    ASSERT_TRUE(slayer3d_game_data_load_file(dojo_path.string().c_str(), session, &runtime, error, sizeof(error)))
        << error;

    const slayer3d_properties *scene_state = slayer3d_game_data_scene_state(runtime);
    ASSERT_NE(scene_state, nullptr);
    slayer3d_input_manager *input = slayer3d_game_session_get_input(session);
    ASSERT_NE(input, nullptr);

    editor_brush_source_prefab_result slab_result{};
    const int slab_min[3] = {-500, 0, -1500};
    const int slab_max[3] = {500, 200, -500};
    ASSERT_TRUE(slayer3d_game_data_create_editor_source_box_brush(
        runtime, "brush.editor_shell.target", "mat.editor.floor", SLAYER3D_GAME_DATA_BRUSH_CONTENT_SOLID, slab_min,
        slab_max, &slab_result));
    ASSERT_TRUE(slab_result.valid);
    ASSERT_STRNE(slab_result.brush_name, "");

    editor_brush_source_prefab_result cube_result{};
    const int cube_min[3] = {-500, 200, -500};
    const int cube_max[3] = {500, 1200, 500};
    ASSERT_TRUE(slayer3d_game_data_create_editor_source_box_brush(
        runtime, "brush.editor_shell.target", "mat.editor.wall", SLAYER3D_GAME_DATA_BRUSH_CONTENT_SOLID, cube_min,
        cube_max, &cube_result));
    ASSERT_TRUE(cube_result.valid);
    ASSERT_STRNE(cube_result.brush_name, "");

    auto brush_world = [&]() {
        slayer3d_game_data_brush_world world{};
        EXPECT_TRUE(slayer3d_game_data_get_brush_world(runtime, "brush.editor_shell.target", &world));
        return world;
    };
    auto brush_index = [&](const char *brush_name) {
        const slayer3d_game_data_brush_world world = brush_world();
        for (int i = 0; i < world.brush_count; ++i)
        {
            const slayer3d_game_data_brush &brush = world.brushes[i];
            if (brush.name != nullptr && SDL_strcmp(brush.name, brush_name) == 0)
                return i;
        }
        ADD_FAILURE() << "brush not found: " << (brush_name != nullptr ? brush_name : "<null>");
        return -1;
    };
    auto brush_bounds = [&](const char *brush_name) {
        const slayer3d_game_data_brush_world world = brush_world();
        for (int i = 0; i < world.brush_count; ++i)
        {
            const slayer3d_game_data_brush &brush = world.brushes[i];
            if (brush.name != nullptr && SDL_strcmp(brush.name, brush_name) == 0)
                return brush.bounds;
        }
        ADD_FAILURE() << "brush not found: " << (brush_name != nullptr ? brush_name : "<null>");
        return slayer3d_bounding_box{};
    };
    auto click_editor = [&](float x, float y, Uint64 frame) {
        SDL_Event click_motion{};
        click_motion.type = SDL_EVENT_MOUSE_MOTION;
        click_motion.motion.x = x;
        click_motion.motion.y = y;
        SDL_Event mouse_down{};
        mouse_down.type = SDL_EVENT_MOUSE_BUTTON_DOWN;
        mouse_down.button.button = SDL_BUTTON_LEFT;
        mouse_down.button.x = x;
        mouse_down.button.y = y;
        slayer3d_input_process_event(input, &click_motion);
        slayer3d_input_process_event(input, &mouse_down);
        slayer3d_input_update(input, frame);
        EXPECT_TRUE(slayer3d_game_data_update_active_editor_tooling(runtime));
        mouse_down.type = SDL_EVENT_MOUSE_BUTTON_UP;
        slayer3d_input_process_event(input, &mouse_down);
        slayer3d_input_update(input, frame + 1U);
    };
    auto ui_rect = [&](const char *name) {
        struct RectCapture
        {
            const slayer3d_game_data_runtime *runtime = nullptr;
            const char *name = nullptr;
            slayer3d_game_data_ui_rect rect{};
            bool found = false;
        } capture{runtime, name, {}, false};
        auto capture_rect = [](void *userdata, const slayer3d_game_data_ui_rect *rect) -> bool {
            auto *capture = static_cast<RectCapture *>(userdata);
            if (rect == nullptr || rect->name == nullptr || capture->name == nullptr ||
                SDL_strcmp(rect->name, capture->name) != 0)
            {
                return true;
            }
            if (slayer3d_game_data_ui_rect_is_visible(capture->runtime, rect, nullptr))
            {
                capture->rect = *rect;
                capture->found = true;
                return false;
            }
            return true;
        };
        EXPECT_TRUE(slayer3d_game_data_for_each_ui_rect(runtime, capture_rect, &capture));
        if (!capture.found)
            ADD_FAILURE() << "visible rect not found: " << (name != nullptr ? name : "<null>");
        return capture.rect;
    };

    slayer3d_game_data_editor_selection slab_selection{};
    slayer3d_game_data_editor_selection cube_selection{};
    ASSERT_TRUE(editor_selection_from_brush_index(runtime, "brush.editor_shell.target",
                                                  brush_index(slab_result.brush_name), -1, &slab_selection));
    ASSERT_TRUE(editor_selection_from_brush_index(runtime, "brush.editor_shell.target",
                                                  brush_index(cube_result.brush_name), -1, &cube_selection));

    SDL_SetModState(SDL_KMOD_NONE);
    ASSERT_TRUE(editor_select_mode_primary_click(runtime, &slab_selection));
    SDL_SetModState(SDL_KMOD_SHIFT);
    ASSERT_TRUE(editor_select_mode_primary_click(runtime, &cube_selection));
    SDL_SetModState(SDL_KMOD_NONE);
    ASSERT_EQ(slayer3d_properties_get_int(scene_state, "editor.selection.count", 0), 2);
    ASSERT_TRUE(slayer3d_properties_get_bool(scene_state, "editor.selection.multiple", false));

    const slayer3d_bounding_box slab_before = brush_bounds(slab_result.brush_name);
    const slayer3d_bounding_box cube_before = brush_bounds(cube_result.brush_name);
    ASSERT_NEAR(slab_before.min.z, -1.5f, 0.001f);
    ASSERT_NEAR(slab_before.max.z, -0.5f, 0.001f);
    ASSERT_NEAR(cube_before.min.z, -0.5f, 0.001f);
    ASSERT_NEAR(cube_before.max.z, 0.5f, 0.001f);

    const slayer3d_game_data_ui_rect flip_horizontal_rect =
        ui_rect("ui.editor_shell.tool_toolbar.flip_horizontal.button");
    click_editor(flip_horizontal_rect.x + flip_horizontal_rect.w * 0.5f,
                 flip_horizontal_rect.y + flip_horizontal_rect.h * 0.5f, 200);

    EXPECT_FALSE(slayer3d_properties_get_bool(scene_state, "editor.grid.menu.open", false));
    EXPECT_TRUE(slayer3d_properties_get_bool(scene_state, "editor.flip_horizontal.valid", false));
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.flip_horizontal.message", ""),
                 "flipped selected brushes horizontally around +Z");
    EXPECT_STREQ(slayer3d_properties_get_string(scene_state, "editor.tool.last_action", ""),
                 "flipped 2 selected brushes horizontally");

    const slayer3d_bounding_box slab_after = brush_bounds(slab_result.brush_name);
    const slayer3d_bounding_box cube_after = brush_bounds(cube_result.brush_name);
    EXPECT_NEAR(slab_after.min.z, -0.5f, 0.001f);
    EXPECT_NEAR(slab_after.max.z, 0.5f, 0.001f);
    EXPECT_NEAR(cube_after.min.z, -1.5f, 0.001f);
    EXPECT_NEAR(cube_after.max.z, -0.5f, 0.001f);
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.selection.count", 0), 2);

    ASSERT_TRUE(slayer3d_game_data_undo_editor_command(runtime, nullptr, nullptr));
    const slayer3d_bounding_box slab_undo = brush_bounds(slab_result.brush_name);
    const slayer3d_bounding_box cube_undo = brush_bounds(cube_result.brush_name);
    EXPECT_NEAR(slab_undo.min.z, slab_before.min.z, 0.001f);
    EXPECT_NEAR(slab_undo.max.z, slab_before.max.z, 0.001f);
    EXPECT_NEAR(cube_undo.min.z, cube_before.min.z, 0.001f);
    EXPECT_NEAR(cube_undo.max.z, cube_before.max.z, 0.001f);
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.selection.count", 0), 2);

    ASSERT_TRUE(slayer3d_game_data_redo_editor_command(runtime, nullptr, nullptr));
    const slayer3d_bounding_box slab_redo = brush_bounds(slab_result.brush_name);
    const slayer3d_bounding_box cube_redo = brush_bounds(cube_result.brush_name);
    EXPECT_NEAR(slab_redo.min.z, slab_after.min.z, 0.001f);
    EXPECT_NEAR(slab_redo.max.z, slab_after.max.z, 0.001f);
    EXPECT_NEAR(cube_redo.min.z, cube_after.min.z, 0.001f);
    EXPECT_NEAR(cube_redo.max.z, cube_after.max.z, 0.001f);
    EXPECT_EQ(slayer3d_properties_get_int(scene_state, "editor.selection.count", 0), 2);

    slayer3d_game_data_destroy(runtime);
    slayer3d_game_session_destroy(session);
}

