TEST(GameDataRuntime, SlayerMapRejectsInvalidDocuments)
{
    struct Case
    {
        const char *name;
        const char *json;
        const char *expected;
    };
    const Case cases[] = {{"format", R"json({"format":"wrong","version":1})json", "format must be 'slayer3d.map'"},
                          {"duplicate_object",
                           R"json({
  "format": "slayer3d.map",
  "version": 1,
  "brushes": [
    { "id": "object.same", "geometry": { "kind": "box", "min": [0, 0, 0], "max": [1, 1, 1] } }
  ],
  "actors": [
    { "id": "object.same", "primitive": "capsule" }
  ]
})json",
                           "duplicate object id"},
                          {"unknown_material",
                           R"json({
  "format": "slayer3d.map",
  "version": 1,
  "brushes": [
    {
      "id": "brush.one",
      "geometry": { "kind": "box", "min": [0, 0, 0], "max": [1, 1, 1] },
      "material": "mat.missing"
    }
  ]
})json",
                           "unknown material reference"},
                          {"unknown_connection_endpoint",
                           R"json({
  "format": "slayer3d.map",
  "version": 1,
  "actors": [
    { "id": "actor.one", "primitive": "box" }
  ],
  "connections": [
    {
      "from": { "entity": "actor.one", "event": "triggered" },
      "to": { "entity": "actor.missing", "action": "open" }
    }
  ]
})json",
                           "unknown connection endpoint entity"},
                          {"bad_box",
                           R"json({
  "format": "slayer3d.map",
  "version": 1,
  "brushes": [
    { "id": "brush.bad", "geometry": { "kind": "box", "min": [1, 0, 0], "max": [1, 1, 1] } }
  ]
})json",
                           "box geometry max must be greater than min"},
                          {"bad_display_mode",
                           R"json({
  "format": "slayer3d.map",
  "version": 1,
  "actors": [
    { "id": "actor.bad", "primitive": "box", "display_mode": "ghost" }
  ]
})json",
                           "actor display_mode must be solid or wireframe"},
                          {"bad_global_tonemap",
                           R"json({
  "format": "slayer3d.map",
  "version": 1,
  "global": {
    "tonemap": "cinematic"
  }
})json",
                           "global tonemap must be none, reinhard, or aces"},
                          {"bad_global_fog_range",
                           R"json({
  "format": "slayer3d.map",
  "version": 1,
  "global": {
    "fog": { "mode": "linear", "start": 8, "end": 4 }
  }
})json",
                           "global fog end must be greater than start"},
                          {"bad_light_type",
                           R"json({
  "format": "slayer3d.map",
  "version": 1,
                          "lights": [
                            { "id": "light.bad", "type": "volumetric" }
                          ]
})json",
                           "light type must be directional, point, spot, area_rect, or area_sphere"},
                          {"bad_spot_cone_order",
                           R"json({
  "format": "slayer3d.map",
  "version": 1,
  "lights": [
    { "id": "light.bad", "type": "spot", "inner_angle_degrees": 50, "outer_angle_degrees": 25 }
  ]
})json",
                           "spot light outer_angle_degrees must be greater than or equal to inner_angle_degrees"},
                          {"bad_area_rect_shape",
                           R"json({
  "format": "slayer3d.map",
  "version": 1,
  "lights": [
    { "id": "light.bad", "type": "area_rect", "width": 2.0 }
  ]
})json",
                           "area_rect light requires positive width and height"},
                          {"bad_area_sphere_shape",
                           R"json({
  "format": "slayer3d.map",
  "version": 1,
  "lights": [
    { "id": "light.bad", "type": "area_sphere" }
  ]
})json",
                           "area_sphere light requires a positive radius"},
                          {"bad_light_animation",
                           R"json({
  "format": "slayer3d.map",
  "version": 1,
  "lights": [
    {
      "id": "light.bad",
      "type": "point",
      "animation": { "type": "flicker", "min_intensity": 2, "max_intensity": 1 }
    }
  ]
})json",
                           "light animation max_intensity must be greater than or equal to min_intensity"}};

    for (const Case &test_case : cases)
    {
        char error[512]{};
        EXPECT_FALSE(
            slayer3d_map_validate_json(test_case.json, SDL_strlen(test_case.json), nullptr, error, sizeof(error)))
            << test_case.name;
        EXPECT_NE(std::string(error).find(test_case.expected), std::string::npos) << test_case.name << ": " << error;
    }
}

